extern volatile bool ack_received;
/* TIM3: 16-bit counter, 1 tick = 1 us */
bool wait_ack(void) {
    uint16_t start = TIM3->CNT;
    while (!ack_received) {
        uint16_t now = TIM3->CNT;
        if (now - start > 5000)
            return false;
    }
    return true;
}

// on_tick() stores the callback.
// The timer ISR calls it later.
void start_blink(Timer& t) {
    int period_ms = 500;
    t.on_tick([&] {
        led_toggle_every(period_ms);
    });
}

